$('new').onclick=()=>{const body=dialog('new');body.append(el('p','',t('newConfirm')));const b=el('button','primary',t('new'));b.onclick=()=>{snapshot();if(mode==='grammar')grammar='';if(mode==='regex')expression='';model={type:['fa','pda','tm'].includes(mode)?mode:'fa',states:[],edges:[]};selected=null;$('dialog').close();changed()};body.append(b)};
$('library').onclick=()=>{const body=dialog('library');for(const[k,key]of[['fa','exampleFA'],['pda','examplePDA'],['tm','exampleTM']]){const b=el('button','library-card');b.append(el('b','',t(k)),el('small','',t(key)));b.onclick=()=>{snapshot();mode=k;model=example(k);selected=null;$('word').value=k==='pda'?'aaabbb':k==='tm'?'0101':'1011';$('dialog').close();changed()};body.append(b)}};$('guide').onclick=()=>dialog('guide').append(el('p','',t('guideText')));$('closeDialog').onclick=()=>$('dialog').close();$('dialog').onclick=e=>{if(e.target===$('dialog'))$('dialog').close()};
$('export').onclick=()=>{const body=dialog('export');for(const name of['JSON','JFLAP (.jff)','SVG']){const b=el('button','library-card',name);b.onclick=()=>action(()=>{if(name==='JSON')download(JSON.stringify({version:1,model,mode,grammar,expression},null,2),'automata-project.json','application/json');else if(name.startsWith('JFLAP'))download(jflap(model),'automata.jff','application/xml');else{const s=$('canvas').cloneNode(true);s.querySelectorAll('.flow-line,.state-halo').forEach(e=>e.remove());const fitted=fitCamera(model.states,routes.map(x=>x.route));s.setAttribute('viewBox',`${fitted.x} ${fitted.y} ${fitted.w} ${fitted.h}`);s.setAttribute('xmlns',ns);const style=svg('style',{},'.state circle{fill:#fff;stroke:#7353d6;stroke-width:2}.state text{fill:#42355f;font:19px sans-serif}.edge path,.initial-arrow{fill:none;stroke:#9d9ab8;stroke-width:2}.edge text{font:15px sans-serif;fill:#625d7e}.edge .hit{display:none}');s.prepend(style);download(new XMLSerializer().serializeToString(s),'automata.svg','image/svg+xml')}$('dialog').close()});body.append(b)}};
function loadProject(text){if(text.length>2e6)throw Error('modelLimit');const next=importProject(text);snapshot();model=next;mode=next.type;closeContext();camera=fitCamera(model.states,groupRoutes().map(x=>x.route));if(text.trim().startsWith('{')){const data=JSON.parse(text);if(['fa','pda','tm','grammar','regex'].includes(data.mode))mode=data.mode;if(typeof data.grammar==='string')grammar=data.grammar;if(typeof data.expression==='string')expression=data.expression}changed()}
$('import').onclick=()=>{const body=dialog('import'),fileButton=el('button','',t('import')+' (.json / .jff)'),label=el('label','',t('pasteFile')),area=el('textarea'),apply=el('button','primary',t('apply'));area.id='pasteProject';area.rows=7;area.maxLength=2000000;label.htmlFor=area.id;fileButton.onclick=()=>$('file').click();apply.onclick=()=>action(()=>{loadProject(area.value);$('dialog').close()});body.append(fileButton,label,area,apply)};
$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;try{if(f.size>2e6)throw Error('modelLimit');loadProject(await f.text());$('dialog').close()}catch(e){toast(e.message in dict?e.message:'invalidModel')}$('file').value=''};
$('language').onchange=()=>language($('language').value);document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('dialog').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click()}if(e.key==='Delete'&&selected)$('inspector').querySelector('.danger')?.click();if(e.key==='Escape'){source=null;tool='select';closeContext();stopAnimation();render()}});
await language(['pt','en','fr','es','zh','hi'].includes(lang)?lang:'pt');

$('tools').onclick=()=>{const body=dialog('tools');const option=(key,fn)=>{const b=el('button','library-card',t(key));b.onclick=()=>action(fn);body.append(b)};if(model.type==='fa'&&mode!=='grammar'){option('toRegex',()=>{const regex=toRegex(model);expression=regex;mode='regex';result=null;$('dialog').close();changed()});option('toGrammar',()=>{grammar=toGrammar(model);mode='grammar';result=null;$('dialog').close();changed()});option('equivalence',()=>{const input=el('input');input.type='file';input.accept='.json,.jff,.xml';input.onchange=async()=>{try{const f=input.files[0];if(!f||f.size>2e6)throw Error('modelLimit');const other=importProject(await f.text()),r=equivalence(model,other);body.append(el('p','',r.equivalent?t('equivalent'):t('witness')+': '+(r.witness||'ε')))}catch(e){toast(e.message in dict?e.message:'invalidModel')}};body.append(input);input.click()})}if(mode==='grammar'){option('grammarFA',()=>{const next=regularGrammarToFA(grammar);snapshot();model=next;mode='fa';$('dialog').close();changed()});option('grammarPDA',()=>{const next=grammarToPDA(grammar);snapshot();model=next;mode='pda';$('dialog').close();changed()})}};

function stopAnimation(){if(playTimer){clearInterval(playTimer);playTimer=null}if($('animate'))$('animate').replaceChildren(document.createTextNode('▶ '+t('animate')));if($('quickAnimate')){$('quickAnimate').textContent='▶';$('quickAnimate').title=t('animate');$('quickAnimate').setAttribute('aria-label',t('animate'))}}
function playAnimation(){
 closeContext();if(!result||!result.trace||frame>=result.trace.length-1){result=compute();frame=0}
 if(!result.trace||result.trace.length<2){render();return}
 playTimer=setInterval(()=>{frame++;if(frame>=result.trace.length-1){frame=result.trace.length-1;stopAnimation()}render()},Number($('animationSpeed').value));render();
}
$('animate').onclick=()=>action(()=>{if(playTimer){stopAnimation();render()}else playAnimation()});
$('animationSpeed').onchange=()=>{if(playTimer){stopAnimation();playAnimation()}};
$('closeContext').onclick=()=>{closeContext();renderCanvas()};
$('contextMenu').onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();closeContext();$('canvas').focus();renderCanvas()}};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#contextMenu,.state,.edge,.canvas-toolbar'))closeContext()});
const zoom=(factor,anchor)=>{camera=zoomCamera(camera,factor,anchor);applyCamera()};
$('zoomIn').onclick=()=>zoom(1.25);$('zoomOut').onclick=()=>zoom(.8);
$('zoomReset').onclick=()=>{camera={x:camera.x+(camera.w-980)/2,y:camera.y+(camera.h-560)/2,w:980,h:560};applyCamera()};
$('fitView').onclick=()=>{camera=fitCamera(model.states,routes.map(x=>x.route));applyCamera()};
$('canvas').addEventListener('wheel',e=>{e.preventDefault();closeContext();zoom(Math.exp(-Math.max(-100,Math.min(100,e.deltaY))*.003),point(e))},{passive:false});
$('focusEditor').onclick=()=>{document.body.classList.toggle('editor-focus');closeContext();requestAnimationFrame(applyCamera);$('canvas').focus()};
window.addEventListener('resize',()=>requestAnimationFrame(positionContext));
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('dialog').open)return;if(e.code==='Space'){e.preventDefault();spaceHeld=true;$('canvas').classList.add('space-pan')}if(e.key==='Escape'&&document.body.classList.contains('editor-focus'))document.body.classList.remove('editor-focus');if(e.target.closest('#canvas')){if(e.key==='+'||e.key==='='){e.preventDefault();zoom(1.25)}if(e.key==='-'){e.preventDefault();zoom(.8)}if(e.key==='0')$('fitView').click()}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){spaceHeld=false;$('canvas').classList.remove('space-pan')}});
window.addEventListener('blur',()=>{spaceHeld=false;stopAnimation();$('canvas').classList.remove('space-pan')});

$('quickAnimate').onclick=()=>$('animate').click();$('quickStep').onclick=()=>$('step').click();$('quickReset').onclick=()=>$('reset').click();$('quickWord').oninput=()=>{$('word').value=$('quickWord').value;$('word').oninput()};$('quickWord').onkeydown=e=>{if(e.key==='Enter')$('animate').click()};

$('clearEditor').onclick=()=>{
 const body=dialog('clearEditor'),message=el('p','',t('clearEditorConfirm')),actions=el('div','dialog-actions');
 const cancel=el('button','',t('cancel')),confirm=el('button','primary',t('clearEditor'));
 cancel.onclick=()=>$('dialog').close();
 confirm.onclick=()=>{snapshot();model={type:model.type,states:[],edges:[]};selected=null;source=null;drag=null;tool='select';frame=0;camera={x:0,y:0,w:980,h:560};$('batchResults').replaceChildren();$('dialog').close();changed()};
 actions.append(cancel,confirm);body.append(message,actions);cancel.focus();
};
